<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {networkUtilityWindow,networkUtilityCapabilities,NETWORK_TABS,NETWORK_TAB_LABELS} from './network-utility-state.js';
 import {networkInfoLines,networkServiceInfo} from './network-utility-diagnostics.js';
 import {networkUtilityMenus} from './network-utility-menus.js';
 import {createNetworkUtilityNativeView} from './network-utility-native-view.js';
 import './network-utility.css';
 let {window,state: networkUtilityState,profile,execute,registerView=()=>{},available=true,active=true,controls={},preferences=null,wifi=null,inventory=null,showMenuBar=false}=$props();
 let root=$state(),message=$state('');let busy=false,originalState,originalProfile,originalWindow,originalRoot,originalSession,retired=false;
 let w=$derived(networkUtilityWindow(networkUtilityState,window.id)),cap=$derived(networkUtilityCapabilities(profile));
 let network=$derived(preferences?.configuration?.network),info=$derived(network&&wifi&&inventory&&w?networkInfoLines(network,wifi,inventory,w.serviceId):[]);
 let service=$derived(network&&wifi&&w?networkServiceInfo(network,wifi,w.serviceId):null);
 let menus=$derived(networkUtilityMenus({state: networkUtilityState,profile,windowId:window.id}));
 function current(){return !retired&&root===originalRoot&&root?.isConnected===true&&networkUtilityState===originalState&&profile===originalProfile&&window===originalWindow&&w===originalSession;}
 async function send(suffix,payload={}){if(!current()||!available||!active)return;const r=await execute(`networkutility.${suffix}`,{windowId:window.id},payload);if(current())message=r?.status==='rejected'?r.error?.message??'Operation unavailable.':'';return r;}
 async function menuItem(item){if(!current()||!available||!active||!item.enabled)return;await send('sheet',{menu:null});if(!current())return;const r=await execute(item.request.command,item.request.target,item.request.payload);if(current())message=r?.status==='rejected'?r.error?.message??'Operation unavailable.':'';}
 onMount(()=>{originalState=networkUtilityState;originalProfile=profile;originalWindow=window;originalRoot=root;originalSession=w;const view=createNetworkUtilityNativeView({getRoot:()=>root,getState:()=>networkUtilityState,windowId:window.id,available:()=>current()&&available&&active&&!window.minimized,tick});registerView(window.id,view);return ()=>{retired=true;view.destroy();registerView(originalWindow.id,null,view);};});
 $effect(()=>{const running=w?.running,session=w,mounted=root;if(!running||!mounted)return;const timer=setInterval(async()=>{if(busy||!current()||!available||!active||w!==session||root!==mounted||!w.running)return;busy=true;try{await send('step');}finally{busy=false;}},450);return ()=>clearInterval(timer);});
 const prompt={ping:'Enter the network address to ping:',lookup:'Enter an internet address to look up:',traceroute:'Enter the network address to trace an internet route to:',whois:'Enter a domain address to look up its “whois” information:',finger:'Enter the user and domain address to use Finger on:',portscan:'Enter an internet or IP address to scan for open ports:'};
 const action={ping:'Ping',lookup:'Lookup',traceroute:'Trace',whois:'Whois',finger:'Finger',portscan:'Scan',netstat:'Netstat',info:'Refresh'};
</script>
{#if w}
<section bind:this={root} class="network-utility-app" class:nu-windows={cap.windows} class:nu-classic={cap.classic} class:nu-golden={cap.golden} aria-label={cap.label}>
 <header class="nu-titlebar">{#if cap.windows}<button class="nu-close" aria-label="Close Network Utility" data-networkutility-control="close" onclick={()=>send('close')}></button>{:else}<WindowControls {active} onclose={()=>send('close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}<strong>{cap.label}</strong><button aria-label="Network Utility Help" data-networkutility-control="help" onclick={()=>send('sheet',{sheet:'help'})}>?</button></header>
 <div class="nu-main" inert={!available||!active||!!w.sheet}>
 {#if showMenuBar||cap.windows}<nav class="nu-menubar" aria-label="Network Utility menus">{#each menus as menu}<button data-networkutility-control={`menu-${menu.id}`} onclick={()=>send('sheet',{menu:w.menu===menu.id?null:menu.id})}>{menu.label}</button>{/each}</nav>{/if}
 {#if w.menu}<div class="nu-menu" role="menu">{#each menus.filter(m=>m.id===w.menu) as menu}{#each menu.children as item}<button role="menuitem" disabled={!item.enabled} onclick={()=>menuItem(item)}>{item.label}</button>{/each}{/each}</div>{/if}
 <nav class="nu-tabs" role="tablist" aria-label="Network diagnostics">{#each NETWORK_TABS as tab}<button role="tab" aria-selected={w.tab===tab} disabled={w.running&&w.tab!==tab} data-networkutility-control={`tab-${tab}`} class:selected={w.tab===tab} onclick={()=>send('tab',{tab})}>{NETWORK_TAB_LABELS[tab]}</button>{/each}</nav>
 {#if !cap.classic}<p class="nu-equivalent">Functional local equivalent · no native Network Utility on this profile</p>{/if}
 <div class="nu-content" role="tabpanel" aria-label={NETWORK_TAB_LABELS[w.tab]}>
 {#if w.tab==='info'}
  <label class="nu-interface">Network Interface:<select data-networkutility-control="interface" aria-label="Network interface" value={w.serviceId??network?.preferredServiceId??''} onchange={(e)=>send('configure',{serviceId:e.currentTarget.value})}>{#each network?.services??[] as s}<option value={s.id}>{s.kind==='wifi'?'Wi-Fi':s.kind==='ethernet'?'Ethernet':'VPN'} ({s.id})</option>{/each}</select></label>
  {#if service}<div class="nu-info"><dl><dt>IP Address:</dt><dd>{service.connected?service.address:'Not connected'}</dd><dt>Link Speed:</dt><dd>{service.speed} · authored</dd><dt>Link Status:</dt><dd>{service.connected?'Active':'Inactive'}</dd><dt>Vendor:</dt><dd>JesterOS local scene</dd><dt>Model:</dt><dd>{service.service.kind}</dd></dl><dl><dt>Router:</dt><dd>{service.router}</dd><dt>Subnet:</dt><dd>{service.subnet}</dd><dt>DNS:</dt><dd>{service.dns.join(', ')}</dd><dt>Network:</dt><dd>{service.networkRow?.name??'Local service'}</dd></dl></div>{:else}<p>Canonical Preferences network source unavailable.</p>{/if}
  <h3>Transfer Statistics · canonical process counters</h3>
 {:else if w.tab==='netstat'}
  <p>Select the information you want to display:</p><fieldset class="nu-radio"><legend class="nu-sr">Netstat information</legend>{#each [['routes','Display routing table information'],['statistics','Display comprehensive network statistics for each protocol'],['multicast','Display multicast information'],['connections','Display the state of all current socket connections']] as row}<label><input type="radio" name={`netstat-${window.id}`} data-networkutility-control={`netstat-${row[0]}`} checked={w.netstatMode===row[0]} disabled={w.running} onchange={()=>send('configure',{netstatMode:row[0]})}/>{row[1]}</label>{/each}</fieldset>
 {:else}
  <label class="nu-host">{prompt[w.tab]}<input type="text" data-networkutility-control="host" aria-label="Network address" maxlength="256" value={w.host} disabled={w.running} onchange={(e)=>send('configure',{host:e.currentTarget.value})}/></label>
  {#if w.tab==='ping'}<fieldset class="nu-radio nu-ping"><legend class="nu-sr">Ping count</legend><label><input type="radio" name={`ping-${window.id}`} checked={w.continuous} disabled={w.running} onchange={()=>send('configure',{continuous:true})}/>Send an unlimited number of pings <small>(local safety limit: 64)</small></label><label><input type="radio" name={`ping-${window.id}`} checked={!w.continuous} disabled={w.running} onchange={()=>send('configure',{continuous:false})}/>Send only <input data-networkutility-control="count" aria-label="Number of pings" type="number" min="1" max="64" value={w.count} disabled={w.running} onchange={(e)=>send('configure',{count:Number(e.currentTarget.value)})}/> pings</label></fieldset>{/if}
  {#if w.tab==='lookup'}<label class="nu-option">Select the information to look up:<select data-networkutility-control="lookup-type" value={w.lookupType} disabled={w.running} onchange={(e)=>send('configure',{lookupType:e.currentTarget.value})}>{#each [['A','Internet Address'],['AAAA','IPv6 Address'],['MX','Mail Exchange'],['NS','Name Server'],['TXT','Text'],['PTR','Pointer'],['ANY','All Information']] as row}<option value={row[0]}>{row[1]}</option>{/each}</select></label>{/if}
  {#if w.tab==='whois'}<label class="nu-option">Whois Server:<select aria-label="Whois server"><option>Scene Registry · fictional local equivalent</option></select></label>{/if}
  {#if w.tab==='finger'}<p class="nu-note">Example: login@localhost. Accounts come only from the canonical local account inventory.</p>{/if}
  {#if w.tab==='portscan'}<label class="nu-ports">Only test ports between <input data-networkutility-control="port-from" aria-label="First port" type="number" min="1" max="65535" value={w.portFrom} disabled={w.running} onchange={(e)=>send('configure',{portFrom:Number(e.currentTarget.value)})}/> and <input data-networkutility-control="port-to" aria-label="Last port" type="number" min="1" max="65535" value={w.portTo} disabled={w.running} onchange={(e)=>send('configure',{portTo:Number(e.currentTarget.value)})}/></label><p class="nu-note">At most 4096 ports; only actual canonical local listener records can be open.</p>{/if}
 {/if}
 <div class="nu-actions"><small>Targets: localhost, router.scene.example, scene.example · authored only</small><button data-networkutility-control="start" class="nu-default" disabled={w.running||!network||!wifi||!inventory} onclick={()=>send('start')}>{action[w.tab]}</button><button data-networkutility-control="stop" disabled={!w.running} onclick={()=>send('stop')}>Stop</button></div>
 <pre class="nu-results" data-networkutility-results data-networkutility-control="results" tabindex="0" aria-label="Diagnostic results">{(w.tab==='info'?info:w.lines).join('\n')}</pre>
 </div>
 <footer><span role="status">{message||w.status}</span><button data-networkutility-control="clear" disabled={w.running} onclick={()=>send('clear')}>Clear</button></footer>
 </div>
 {#if w.sheet==='help'}<section class="nu-sheet" role="dialog" aria-modal="true" aria-label="Network Utility Help"><h2>Network Utility</h2><p>{cap.disclosure}</p><p>Info reads active canonical service settings and process counters. Netstat displays configured routes, actual process byte counters and registered protocol endpoints. Ping and Traceroute advance deterministic fictional samples and Stop cancels further samples. Lookup and Whois query the authored .example namespace, not an internet service. Finger reads registered local user records only; an absent account service reports unavailable. Port Scan walks bounded ranges and reports only actual local listeners.</p><p>Changing a canonical source during a run stops it safely. Unknown addresses fail locally rather than receiving invented host replies.</p><button data-networkutility-control="help-done" onclick={()=>send('sheet',{sheet:null})}>Done</button></section>{/if}
</section>
{/if}
